<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_auth();
$pdo=db(); $error=''; $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$active=isset($_POST['is_active'])?1:0;$cat=(int)($_POST['category_id']??0)?:null;if($name===''||$price<0){$error='Nom et prix valides requis.';}else{try{$slug=slugify($name);if($id){$s=$pdo->prepare('UPDATE products SET category_id=?,name=?,slug=?,description=?,price=?,stock=?,is_active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([$cat,$name,$slug,$desc,$price,$stock,$active,$id]);}else{$s=$pdo->prepare('INSERT INTO products(category_id,name,slug,description,price,stock,is_active) VALUES(?,?,?,?,?,?,?)');$s->execute([$cat,$name,$slug,$desc,$price,$stock,$active]);$id=(int)$pdo->lastInsertId();}if(!empty($_FILES['image']['tmp_name'])){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)throw new RuntimeException('Image invalide ou > 5 Mo.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('JPG, PNG ou WebP uniquement.');if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime];$file=bin2hex(random_bytes(12)).'.'.$ext;move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$file);$pdo->prepare('UPDATE products SET image=? WHERE id=?')->execute([$file,$id]);}redirect('/admin/products.php');}catch(Throwable $e){$error=$e->getMessage();}}}
if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Produits</title><link rel="stylesheet" href="/public/css/app.css"></head><body><header class="top"><a class="brand" href="/admin/">Dashboard</a><nav><a href="/admin/products.php">Produits</a><a href="/admin/categories.php">Catégories</a><a href="/admin/settings.php">Paramètres</a></nav></header><main class="container"><div class="section-head"><h1><?= $edit?'Modifier':'Produits'?></h1><?php if(!$edit):?><a class="btn primary" href="?action=new">+ Ajouter</a><?php endif;?></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($edit||isset($_GET['action'])):?><form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Nom<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Catégorie<select name="category_id"><option value="0">Sans catégorie</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$edit&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Prix FCFA<input type="number" step="1" min="0" name="price" value="<?=e((string)($edit['price']??0))?>" required></label><label>Stock<input type="number" min="0" name="stock" value="<?=e((string)($edit['stock']??0))?>"></label><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="check"><input type="checkbox" name="is_active" <?=$edit===null||($edit['is_active']??1)?'checked':''?>> Produit visible</label><button class="btn primary">Enregistrer</button></form><?php endif;?><div class="list"><?php foreach($products as $p):?><article class="row"><div><?php if($p['image']):?><img class="thumb" src="/<?=e(UPLOAD_URL.$p['image'])?>" alt=""><?php endif;?><div><b><?=e($p['name'])?></b><small><?=money($p['price'])?> · Stock <?=$p['stock']?> · <?=e($p['category_name']??'')?></small></div></div><a href="?edit=<?=$p['id']?>">Modifier</a></article><?php endforeach;?></div></main></body></html>